UPDATE sku_stock
SET available_stocks = available_stocks - #{qty},
    reserved_stocks = reserved_stocks + #{qty},
    update_time = #{updateTime}
WHERE sku_id = #{skuId}
  AND available_stocks >= #{qty}

UPDATE sku_stock
SET available_stocks = available_stocks + #{qty},
    reserved_stocks = reserved_stocks - #{qty},
    update_time = #{updateTime}
WHERE sku_id = #{skuId}
  AND reserved_stocks >= #{qty}

UPDATE sku_stock
SET reserved_stocks = reserved_stocks - #{qty},
    update_time = #{updateTime}
WHERE sku_id = #{skuId}
  AND reserved_stocks >= #{qty}
